solution.code:
function buatAplikasi(files, meta = {}) {
  const halaman = [];
  const layouts = new Set();
  const globalFiles = [];

  for (const f of files) {
    if (f.startsWith("app/pages/") && f.endsWith(".vue")) {
      const segs = f.slice("app/pages/".length, -".vue".length).split("/");
      if (segs[segs.length - 1] === "index") segs.pop();
      halaman.push({ file: f, segs });
    } else if (f.startsWith("app/layouts/") && f.endsWith(".vue")) {
      layouts.add(f.slice("app/layouts/".length, -".vue".length));
    } else if (f.startsWith("app/middleware/") && f.endsWith(".global.ts")) {
      globalFiles.push(f.slice("app/middleware/".length));
    }
  }
  const global = globalFiles.sort().map((f) => f.slice(0, -".global.ts".length));

  // 0 = statis, 1 = [param], 2 = [...param]
  function jenis(seg) {
    if (/^\[\.\.\..+\]$/.test(seg)) return 2;
    if (/^\[.+\]$/.test(seg)) return 1;
    return 0;
  }

  function cocok(segs, bagian) {
    const params = {};
    for (let i = 0; i < segs.length; i++) {
      const s = segs[i];
      const j = jenis(s);
      if (j === 2) {
        params[s.slice(4, -1)] = bagian.slice(i);
        return params;
      }
      if (i >= bagian.length) return null;
      if (j === 1) params[s.slice(1, -1)] = bagian[i];
      else if (s !== bagian[i]) return null;
    }
    return segs.length === bagian.length ? params : null;
  }

  // true bila a lebih spesifik daripada b, dibandingkan dari segmen paling kiri
  function lebihSpesifik(a, b) {
    const n = Math.max(a.length, b.length);
    for (let i = 0; i < n; i++) {
      const x = i < a.length ? jenis(a[i]) : 0;
      const y = i < b.length ? jenis(b[i]) : 0;
      if (x !== y) return x < y;
    }
    return false;
  }

  function resolve(url) {
    const bagian = url.split("?")[0].split("/").filter(Boolean);
    let terbaik = null;
    for (const h of halaman) {
      const params = cocok(h.segs, bagian);
      if (params && (!terbaik || lebihSpesifik(h.segs, terbaik.segs))) {
        terbaik = { file: h.file, segs: h.segs, params };
      }
    }
    if (!terbaik) {
      return { halaman: null, layout: null, params: {}, middleware: [], statusCode: 404 };
    }
    const m = meta[terbaik.file] || {};
    const nama = m.layout === undefined ? "default" : m.layout;
    const dariMeta = m.middleware === undefined ? [] : [].concat(m.middleware);
    return {
      halaman: terbaik.file,
      layout: nama && layouts.has(nama) ? nama : null,
      params: terbaik.params,
      middleware: global.concat(dariMeta),
    };
  }

  return { resolve };
}

