function keSegmen(file) {
  const s = file.replace(/\.vue$/, "").split("/");
  if (s[s.length - 1] === "index") s.pop();
  return s;
}

function cocok(seg, url) {
  const params = {};
  for (let i = 0; i < seg.length; i++) {
    const s = seg[i];
    if (s.startsWith("[...")) {
      params[s.slice(4, -1)] = url.slice(i);
      return params;
    }
    if (i >= url.length) return null;
    if (s.startsWith("[")) params[s.slice(1, -1)] = url[i];
    else if (s !== url[i]) return null;
  }
  return seg.length === url.length ? params : null;
}

function peringkat(file) {
  if (file.includes("[...")) return 2;
  if (file.includes("[")) return 1;
  return 0;
}

function cocokkanHalaman(files, path) {
  const url = path.split("/").filter(Boolean);
  const urut = [...files].sort((a, b) => peringkat(a) - peringkat(b));
  for (const file of urut) {
    const params = cocok(keSegmen(file), url);
    if (params) return { file, params };
  }
  return null;
}

