  return teks
    .split("-")
    .map((k) => k.charAt(0).toUpperCase() + k.slice(1))
    .join("");
}

function namaKomponen(path) {
  const sisa = path.split("components/")[1].replace(/\.vue$/, "");
  const bagian = sisa.split("/").map(pascal);
  const nama = bagian.pop();
  const awalan = bagian.join("");
  return nama.startsWith(awalan) ? nama : awalan + nama;
}

