function buatPengambil() {
  const cache = {};
  const sumber = {};

  function jalankan(key) {
    const { fn, opsi } = sumber[key];
    cache[key] = (async () => {
      try {
        const hasil = await fn();
        const data = opsi.transform ? opsi.transform(hasil) : hasil;
        return { data, error: null };
      } catch (e) {
        return { data: null, error: e.message };
      }
    })();
    return cache[key];
  }

  function ambil(key, fn, opsi = {}) {
    if (cache[key]) return cache[key];
    sumber[key] = { fn, opsi };
    return jalankan(key);
  }

  function refresh(key) {
    return jalankan(key);
  }

  return { ambil, refresh };
}

