solution.code:
function buatServer(handlers) {
  return async function panggil(method, path, opsi = {}) {
    const nama = path.slice("/api/".length);
    const handler = handlers[nama + "." + method.toLowerCase() + ".ts"] || handlers[nama + ".ts"];
    if (!handler) {
      const ada = Object.keys(handlers).some((k) => k.startsWith(nama + "."));
      return ada
        ? { status: 405, body: { message: "Method Not Allowed" } }
        : { status: 404, body: { message: "Not Found" } };
    }
    try {
      const hasil = await handler({ method, query: opsi.query || {}, body: opsi.body });
      return { status: 200, body: hasil };
    } catch (e) {
      if (e && e.status) return { status: e.status, body: { message: e.statusText } };
      return { status: 500, body: { message: "Internal Server Error" } };
    }
  };
}

