function authMiddleware(to, cookies) {
  const sesi = cookies && cookies.sesi;
  const butuhLogin = Boolean(to.meta && to.meta.auth === true);
  if (butuhLogin && !sesi) return { redirect: "/masuk?dari=" + to.path };
  if (to.path === "/masuk" && sesi) return { redirect: "/nilai" };
  return undefined;
}

