solution.code:
function cocok(pola, path) {
  if (pola.endsWith("/**")) {
    const dasar = pola.slice(0, -3);
    return path === dasar || path.startsWith(dasar + "/");
  }
  return pola === path;
}

function aturanRoute(rules, path) {
  const hasil = {};
  Object.keys(rules)
    .filter((pola) => cocok(pola, path))
    .sort((a, b) => a.length - b.length)
    .forEach((pola) => Object.assign(hasil, rules[pola]));
  return hasil;
}

