solution.code:
function namaEnv(kunci, publik) {
  const besar = kunci.replace(/([A-Z])/g, "_$1").toUpperCase();
  return "NUXT_" + (publik ? "PUBLIC_" : "") + besar;
}

function ambil(asal, nilai) {
  if (nilai === undefined) return asal;
  return typeof asal === "number" ? Number(nilai) : nilai;
}

function gabungConfig(bawaan, env) {
  const hasil = {};
  for (const k of Object.keys(bawaan)) {
    if (k !== "public") hasil[k] = ambil(bawaan[k], env[namaEnv(k, false)]);
  }
  hasil.public = {};
  for (const k of Object.keys(bawaan.public || {})) {
    hasil.public[k] = ambil(bawaan.public[k], env[namaEnv(k, true)]);
  }
  return hasil;
}

