solution.code:
function pilihPreset(kebutuhan) {
  const k = kebutuhan || {};
  if (k.statis && k.butuhServer) {
    throw new Error("Situs statis tidak bisa menjalankan server route");
  }
  if (k.statis) return { preset: "static", perintah: "nuxt generate" };
  if (k.platform === "vercel" || k.platform === "netlify") {
    return { preset: k.platform, perintah: "nuxt build" };
  }
  return { preset: "node-server", perintah: "nuxt build" };
}

